public class Main {
    static final int MOD = 100000000;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());

        int n = Integer.parseInt(st.nextToken());
        int d = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());
        String binary = br.readLine().trim();

        // Count total permutations
        long[][] dp = new long[n + 1][1 << Math.min(2*d+1, 20)];
        dp[0][0] = 1;

        for (int i = 0; i < n; i++) {
            for (int mask = 0; mask < (1 << Math.min(2*d+1, 20)); mask++) {
                if (dp[i][mask] == 0) continue;

                for (int j = Math.max(0, i-d); j <= Math.min(n-1, i+d); j++) {
                    int bit = j % Math.min(2*d+1, 20);
                    if ((mask & (1 << bit)) == 0) {
                        int newMask = mask | (1 << bit);
                        dp[i+1][newMask] = (dp[i+1][newMask] + dp[i][mask]) % MOD;
                    }
                }
            }
        }

        long total = 0;
        for (int i = 0; i < (1 << Math.min(2*d+1, 20)); i++) {
            total = (total + dp[n][i]) % MOD;
        }

        System.out.println(total);
        System.out.println(binary);
    }
}

