public class Main {
    static ArrayList<Long> decreasingNums = new ArrayList<>();

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine());

        // Generate all decreasing numbers using combinations
        for (int length = 1; length <= 10; length++) {
            generateCombinations(new ArrayList<>(), 0, length, 9);
        }

        Collections.sort(decreasingNums);

        if (n > decreasingNums.size()) {
            System.out.println(-1);
        } else {
            System.out.println(decreasingNums.get(n - 1));
        }
    }

    static void generateCombinations(ArrayList<Integer> current, int start, int length, int maxDigit) {
        if (current.size() == length) {
            Collections.sort(current, Collections.reverseOrder());
            long num = 0;
            for (int digit : current) {
                num = num * 10 + digit;
            }
            decreasingNums.add(num);
            return;
        }

        for (int i = start; i <= maxDigit; i++) {
            current.add(i);
            generateCombinations(current, i + 1, length, maxDigit);
            current.remove(current.size() - 1);
        }
    }
}

