void generateCombinations(vector<int>& current, int start, int length) {
    if (current.size() == length) {
        sort(current.begin(), current.end(), greater<int>());
        long long num = 0;
        for (int digit : current) {
            num = num * 10 + digit;
        }
        decreasingNums.push_back(num);
        return;
    }

    for (int i = start; i <= 9; i++) {
        current.push_back(i);
        generateCombinations(current, i + 1, length);
        current.pop_back();
    }
}

