def solve():
    n, m = map(int, input().split())
    grid = []
    start = None
    targets = []

    for i in range(n):
        row = input().strip()
        grid.append(row)
        for j in range(m):
            if row[j] == 'S':
                start = (i, j)
            elif row[j] == 'C':
                targets.append((i, j))

    # BFS with state: (row, col, delivered_mask, last_direction)
    # delivered_mask: 0 = none, 1 = first C, 2 = second C, 3 = both
    # last_direction: 0=up, 1=down, 2=left, 3=right

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    queue = deque()

    # Start from all 4 directions
    for d in range(4):
        queue.append((start[0], start[1], 0, d, 0))

    visited = {}

    while queue:
        r, c, mask, last_dir, dist = queue.popleft()

        state = (r, c, mask, last_dir)
        if state in visited:
            continue
        visited[state] = dist

        if mask == 3:
            print(dist)
            return

        for d, (dr, dc) in enumerate(directions):
            if d == last_dir:  # Can't go same direction
                continue

            nr, nc = r + dr, c + dc

            if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] != '#':
                new_mask = mask
                if (nr, nc) == targets[0]:
                    new_mask |= 1
                if (nr, nc) == targets[1]:
                    new_mask |= 2

                new_state = (nr, nc, new_mask, d)
                if new_state not in visited:
                    queue.append((nr, nc, new_mask, d, dist + 1))

    print(-1)

