public class Main {
    static class State {
        int r, c, mask, dir, dist;

        State(int r, int c, int mask, int dir, int dist) {
            this.r = r;
            this.c = c;
            this.mask = mask;
            this.dir = dir;
            this.dist = dist;
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());

        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());

        char[][] grid = new char[n][m];
        int sr = -1, sc = -1;
        int[] tr = new int[2];
        int[] tc = new int[2];
        int targetIdx = 0;

        for (int i = 0; i < n; i++) {
            String line = br.readLine();
            for (int j = 0; j < m; j++) {
                grid[i][j] = line.charAt(j);
                if (grid[i][j] == 'S') {
                    sr = i;
                    sc = j;
                } else if (grid[i][j] == 'C') {
                    tr[targetIdx] = i;
                    tc[targetIdx] = j;
                    targetIdx++;
                }
            }
        }

        int[][] dirs = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        Queue<State> queue = new LinkedList<>();

        for (int d = 0; d < 4; d++) {
            queue.offer(new State(sr, sc, 0, d, 0));
        }

        boolean[][][][] visited = new boolean[n][m][4][4];

        while (!queue.isEmpty()) {
            State cur = queue.poll();

            if (visited[cur.r][cur.c][cur.mask][cur.dir]) continue;
            visited[cur.r][cur.c][cur.mask][cur.dir] = true;

            if (cur.mask == 3) {
                System.out.println(cur.dist);
                return;
            }

            for (int d = 0; d < 4; d++) {
                if (d == cur.dir) continue;

                int nr = cur.r + dirs[d][0];
                int nc = cur.c + dirs[d][1];

                if (nr >= 0 && nr < n && nc >= 0 && nc < m && grid[nr][nc] != '#') {
                    int newMask = cur.mask;
                    if (nr == tr[0] && nc == tc[0]) newMask |= 1;
                    if (nr == tr[1] && nc == tc[1]) newMask |= 2;

                    if (!visited[nr][nc][newMask][d]) {
                        queue.offer(new State(nr, nc, newMask, d, cur.dist + 1));
                    }
                }
            }
        }

        System.out.println(-1);
    }
}

