def solve():
    n, k = map(int, input().split())
    heights = []
    for _ in range(n):
        heights.append(int(input()))

    # DP with bitmask
    # dp[mask][last] = number of ways to arrange students in mask with last as the last student
    dp = [[0] * n for _ in range(1 << n)]

    # Base case: single student
    for i in range(n):
        dp[1 << i][i] = 1

    for mask in range(1 << n):
        for last in range(n):
            if not (mask & (1 << last)):
                continue
            if dp[mask][last] == 0:
                continue

            # Try adding next student
            for next_student in range(n):
                if mask & (1 << next_student):
                    continue

                # Check if height difference > k
                if abs(heights[last] - heights[next_student]) > k:
                    new_mask = mask | (1 << next_student)
                    dp[new_mask][next_student] += dp[mask][last]

    # Sum all complete arrangements
    full_mask = (1 << n) - 1
    result = sum(dp[full_mask])
    print(result)

