            if (!visited[i]) {
                ArrayList<Integer> component = new ArrayList<>();
                dfs(i, component);
                components.add(component);
            }
        }

        int totalEdgesNeeded = 0;

        for (ArrayList<Integer> comp : components) {
            int oddCount = 0;
            for (int node : comp) {
                if (degree[node] % 2 == 1) {
